#!/usr/bin/env python3
"""Panacea's password prompt (polkit, in the island), in the island's own style:
a plain white lock instead of the amber shield, "Password needed", and one
simple line saying what it's for ("Enter your password to run X as
administrator"); polkit's raw message sits behind "Details". Flat Cancel /
Unlock pills like the approval cards.

Patches AuthView.qml. All-or-nothing and idempotent; keeps AuthView.qml.pristine;
if an anchor moved, nothing changes. Re-run by panacea-auth-patch.path after updates.
"""
import os, sys

D = os.path.expanduser("~/.config/panacea")
QML = os.path.join(D, "AuthView.qml")
VERSION = "v1"
PREFIX = "// panacea-local auth patch "

REPL = [('    readonly property var flow: sys.authFlow\n', '    readonly property var flow: sys.authFlow\n    // panacea-local auth patch v1: the island\'s radius system, and a plain-words reason\n    readonly property real islandR: sys.cfg.islandRadius > 0 ? sys.cfg.islandRadius : 26\n    readonly property real boxR: Math.max(14, islandR - 6)\n    readonly property real rInner: Math.max(8, boxR - 6)\n    property bool showDetails: false\n    readonly property string raw: flow ? String(flow.message || "") : ""\n    readonly property string action: flow ? String(flow.actionId || "") : ""\n    readonly property string plain: {\n        // pkexec: "Authentication is needed to run `/usr/bin/bash /path/script.sh\' as the super user"\n        var m = /run [`\'"]([^`\'"]+)[`\'"]/.exec(view.raw);\n        if (m || view.action === "org.freedesktop.policykit.exec") {\n            var words = m ? m[1].trim().split(/\\s+/) : [];\n            var name = words.length ? words[0].split("/").pop() : "";\n            if (["bash", "sh", "zsh", "fish", "python", "python3", "env", "perl"].indexOf(name) >= 0 && words.length > 1)\n                name = words[words[1].charAt(0) === "-" && words.length > 2 ? 2 : 1].split("/").pop();\n            return name ? "Enter your password to run " + name + " as administrator."\n                        : "Enter your password to run a command as administrator.";\n        }\n        var a = view.action;\n        if (/systemd1/.test(a)) return "Enter your password to manage a system service.";\n        if (/NetworkManager|nm-/.test(a)) return "Enter your password to change network settings.";\n        if (/packagekit|pacman|pamac|flatpak/i.test(a)) return "Enter your password to install or remove software.";\n        if (/login1/.test(a)) return "Enter your password to change power or session settings.";\n        if (/udisks/i.test(a)) return "Enter your password to manage a disk.";\n        if (/fprint/i.test(a)) return "Enter your password to change fingerprint settings.";\n        if (/bluez|bluetooth/i.test(a)) return "Enter your password to change Bluetooth settings.";\n        if (/timedate1|hostname1|locale1/.test(a)) return "Enter your password to change system settings.";\n        return "Enter your password to allow this change.";\n    }\n'), ('        RowLayout {\n            Layout.fillWidth: true\n            spacing: 12\n\n            Rectangle {\n                Layout.preferredWidth: 40\n                Layout.preferredHeight: 40\n                radius: 12\n                color: Qt.rgba(0.96, 0.62, 0.04, 0.16)\n                Glyph {\n                    anchors.fill: parent\n                    glyph: String.fromCodePoint(0xF0BC4)      // щит с ключом\n                    color: view.sys.colWarn\n                    fontFam: view.sys.fontFam\n                    size: view.sys.iconSize + 2\n                }\n            }\n\n            ColumnLayout {\n                Layout.fillWidth: true\n                spacing: 1\n                Text {\n                    text: view.sys.tr("Требуются права")\n                    color: view.sys.colFg\n                    font { family: view.sys.fontFam; pixelSize: view.sys.fontSize; bold: true }\n                }\n                Text {\n                    Layout.fillWidth: true\n                    text: view.flow ? String(view.flow.message || "") : ""\n                    color: view.sys.colMuted\n                    wrapMode: Text.WordWrap\n                    font { family: view.sys.fontFam; pixelSize: view.sys.fontSize - 3 }\n                }\n            }\n        }\n\n', '        // panacea-local auth patch v1: a plain lock, a short title and one simple line;\n        // polkit\'s own wording is behind "Details"\n        RowLayout {\n            Layout.fillWidth: true\n            spacing: 12\n\n            Rectangle {\n                Layout.preferredWidth: 38\n                Layout.preferredHeight: 38\n                Layout.alignment: Qt.AlignTop\n                radius: 19\n                color: Qt.rgba(1, 1, 1, 0.08)\n                Glyph {\n                    anchors.fill: parent\n                    glyph: String.fromCodePoint(0xF033E)      // lock\n                    color: view.sys.colFg\n                    fontFam: view.sys.fontFam\n                    size: view.sys.iconSize - 2\n                }\n            }\n\n            ColumnLayout {\n                Layout.fillWidth: true\n                spacing: 3\n                Text {\n                    text: "Password needed"\n                    color: view.sys.colFg\n                    font { family: view.sys.fontFam; pixelSize: view.sys.fontSize; bold: true }\n                }\n                Text {\n                    Layout.fillWidth: true\n                    text: view.plain\n                    color: view.sys.colMuted\n                    wrapMode: Text.WordWrap\n                    font { family: view.sys.fontBody || view.sys.fontFam; pixelSize: view.sys.fontSize - 3 }\n                }\n                Text {\n                    visible: view.raw.length > 0\n                    text: view.showDetails ? "Hide details" : "Details"\n                    color: detMa.containsMouse ? view.sys.colFg : view.sys.colMuted\n                    opacity: 0.8\n                    font { family: view.sys.fontBody || view.sys.fontFam; pixelSize: view.sys.fontSize - 4; underline: detMa.containsMouse }\n                    MouseArea { id: detMa; anchors.fill: parent; anchors.margins: -4; hoverEnabled: true\n                                cursorShape: Qt.PointingHandCursor; onClicked: view.showDetails = !view.showDetails }\n                }\n                Text {\n                    Layout.fillWidth: true\n                    visible: view.showDetails\n                    text: view.raw + (view.action ? "\\n" + view.action : "")\n                    color: view.sys.colMuted\n                    wrapMode: Text.WrapAnywhere\n                    textFormat: Text.PlainText\n                    font { family: view.sys.fontFam; pixelSize: view.sys.fontSize - 5 }\n                }\n            }\n        }\n\n'), ('                    glyph: String.fromCodePoint(0xF033E)\n', '                    glyph: String.fromCodePoint(0xF0306)      // key\n'), ('        RowLayout {\n            Layout.fillWidth: true\n            spacing: 10\n\n            Item { Layout.fillWidth: true }\n\n            Rectangle {\n                Layout.preferredWidth: 104\n                Layout.preferredHeight: 34\n                radius: 11\n                color: cancelMa.containsMouse ? Qt.rgba(1, 1, 1, 0.13) : Qt.rgba(1, 1, 1, 0.06)\n                Behavior on color { ColorAnimation { duration: 150 } }\n                Text {\n                    anchors.centerIn: parent\n                    text: view.sys.tr("Отмена")\n                    color: view.sys.colMuted\n                    font { family: view.sys.fontFam; pixelSize: view.sys.fontSize - 3 }\n                }\n                MouseArea {\n                    id: cancelMa\n                    anchors.fill: parent\n                    hoverEnabled: true\n                    cursorShape: Qt.PointingHandCursor\n                    onClicked: view.cancel()\n                }\n            }\n\n            Rectangle {\n                Layout.preferredWidth: 128\n                Layout.preferredHeight: 34\n                radius: 11\n                color: Qt.rgba(view.sys.colOn.r, view.sys.colOn.g, view.sys.colOn.b,\n                               okMa.containsMouse ? 0.34 : 0.22)\n                border.color: view.sys.colOn\n                border.width: 1\n                Behavior on color { ColorAnimation { duration: 150 } }\n                Text {\n                    anchors.centerIn: parent\n                    text: view.sys.tr("Подтвердить")\n                    color: view.sys.colFg\n                    font { family: view.sys.fontFam; pixelSize: view.sys.fontSize - 3; bold: true }\n                }\n                MouseArea {\n                    id: okMa\n                    anchors.fill: parent\n                    hoverEnabled: true\n                    cursorShape: Qt.PointingHandCursor\n                    onClicked: view.submit()\n                }\n            }\n        }\n    }\n}\n', '        RowLayout {\n            Layout.fillWidth: true\n            spacing: 8\n\n            Item { Layout.fillWidth: true }\n\n            Rectangle {\n                Layout.preferredWidth: 92\n                Layout.preferredHeight: 34\n                radius: view.rInner\n                color: cancelMa.containsMouse ? Qt.rgba(1, 1, 1, 0.14) : Qt.rgba(1, 1, 1, 0.08)\n                Behavior on color { ColorAnimation { duration: 120 } }\n                Text {\n                    anchors.centerIn: parent\n                    text: "Cancel"\n                    color: view.sys.colFg\n                    font { family: view.sys.fontBody || view.sys.fontFam; pixelSize: view.sys.fontSize - 3 }\n                }\n                MouseArea {\n                    id: cancelMa\n                    anchors.fill: parent\n                    hoverEnabled: true\n                    cursorShape: Qt.PointingHandCursor\n                    onClicked: view.cancel()\n                }\n            }\n\n            Rectangle {\n                Layout.preferredWidth: 92\n                Layout.preferredHeight: 34\n                radius: view.rInner\n                color: okMa.pressed ? Qt.rgba(1, 1, 1, 0.8) : view.sys.colFg\n                Behavior on color { ColorAnimation { duration: 120 } }\n                Text {\n                    anchors.centerIn: parent\n                    text: "Unlock"\n                    color: view.sys.colBg\n                    font { family: view.sys.fontBody || view.sys.fontFam; pixelSize: view.sys.fontSize - 3; bold: true }\n                }\n                MouseArea {\n                    id: okMa\n                    anchors.fill: parent\n                    hoverEnabled: true\n                    cursorShape: Qt.PointingHandCursor\n                    onClicked: view.submit()\n                }\n            }\n        }\n    }\n}\n')]


def write(path, text):
    # in place: Quickshell's file watcher loses a file that is swapped for a new one
    with open(path, "r+" if os.path.exists(path) else "w", encoding="utf-8") as f:
        f.seek(0)
        f.write(text)
        f.truncate()


def main():
    cur = open(QML, encoding="utf-8").read()
    if PREFIX + VERSION in cur:
        return 0
    if PREFIX in cur:
        if not os.path.exists(QML + ".pristine"):
            print("auth-patch: older patch but no pristine copy - untouched", file=sys.stderr)
            return 2
        src = open(QML + ".pristine", encoding="utf-8").read()
    else:
        src = cur
    out = src
    for old, new in REPL:
        if out.count(old) != 1:
            print(f"auth-patch: anchor not found: {old.strip()[:60]!r} - untouched", file=sys.stderr)
            return 2
        out = out.replace(old, new, 1)
    if PREFIX not in src:
        write(QML + ".pristine", src)
    write(QML, out)
    print(f"auth-patch: applied {VERSION}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
